export interface ConnectorConfig {
  /** Discord incoming webhook URL (includes webhook ID and token). */
  discordWebhookUrl: string
  /** Optional fetch implementation for testing or customization. */
  fetch?: typeof fetch
}

export interface AirtableWebhookPayload {
  id: string
  fields: Record<string, unknown>
  createdTime: string
}

export interface DiscordWebhookResponse {
  id: string
  channel_id: string
  content: string
}

export interface HandleResult {
  discordMessageId: string
  discordChannelId: string
}

function validatePayload(payload: unknown): asserts payload is AirtableWebhookPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Payload must be an object')
  }
  const p = payload as Record<string, unknown>
  if (typeof p.id !== 'string' || p.id.length === 0) {
    throw new Error('Missing required field: id (string)')
  }
  if (!p.fields || typeof p.fields !== 'object') {
    throw new Error('Missing required field: fields (object)')
  }
  if (typeof p.createdTime !== 'string' || p.createdTime.length === 0) {
    throw new Error('Missing required field: createdTime (string)')
  }
}

function buildDiscordPayload(payload: AirtableWebhookPayload): Record<string, unknown> {
  const embedFields = Object.entries(payload.fields).map(([name, value]) => ({
    name,
    value: String(value),
    inline: true
  }))

  return {
    content: payload.id,
    embeds: [
      {
        fields: embedFields,
        timestamp: payload.createdTime
      }
    ]
  }
}

export async function handle(
  payload: unknown,
  config: ConnectorConfig
): Promise<HandleResult> {
  validatePayload(payload)
  const airtablePayload = payload as AirtableWebhookPayload

  const discordPayload = buildDiscordPayload(airtablePayload)

  const fetchImpl = config.fetch ?? fetch
  const response = await fetchImpl(config.discordWebhookUrl, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(discordPayload)
  })

  if (!response.ok) {
    throw new Error(`Discord webhook request failed: ${response.status} ${response.statusText} at ${config.discordWebhookUrl}`)
  }

  const data = (await response.json()) as DiscordWebhookResponse

  return {
    discordMessageId: data.id,
    discordChannelId: data.channel_id
  }
}

