describe('handle', () => {
  it('sends correctly mapped payload to Discord webhook on happy path', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://discord.com/api/webhooks/abc/def'
        ? jsonResponse({ id: 'msg123', channel_id: 'chan456', content: 'rec123' }, 200)
        : jsonResponse({ error: 'not found' }, 404)
    )

    const payload: AirtableWebhookPayload = {
      id: 'rec123',
      fields: { Name: 'Test Record', Status: 'Active' },
      createdTime: '2024-06-15T12:00:00.000Z'
    }

    const config: ConnectorConfig = {
      discordWebhookUrl: 'https://discord.com/api/webhooks/abc/def',
      fetch
    }

    const result = await handle(payload, config)

    expect(result.discordMessageId).toBe('msg123')
    expect(result.discordChannelId).toBe('chan456')
    expect(calls).toHaveLength(1)
    expect(calls[0].method).toBe('POST')
    expect(calls[0].url).toBe('https://discord.com/api/webhooks/abc/def')
    expect(calls[0].json).toEqual({
      content: 'rec123',
      embeds: [
        {
          fields: [
            { name: 'Name', value: 'Test Record', inline: true },
            { name: 'Status', value: 'Active', inline: true }
          ],
          timestamp: '2024-06-15T12:00:00.000Z'
        }
      ]
    })
