    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { fields: { Name: 'Test' }, createdTime: '2024-01-01T00:00:00.000Z' }
    const config: ConnectorConfig = { discordWebhookUrl: 'https://discord.com/api/webhooks/x/y', fetch }

    await expect(handle(payload as unknown as AirtableWebhookPayload, config)).rejects.toThrow(
      'Missing required field: id (string)'
    )
  })

  it('throws descriptive error when fields is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { id: 'rec123', createdTime: '2024-01-01T00:00:00.000Z' }
    const config: ConnectorConfig = { discordWebhookUrl: 'https://discord.com/api/webhooks/x/y', fetch }

    await expect(handle(payload as unknown as AirtableWebhookPayload, config)).rejects.toThrow(
      'Missing required field: fields (object)'
    )
  })

  it('throws descriptive error when createdTime is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { id: 'rec123', fields: { Name: 'Test' } }
    const config: ConnectorConfig = { discordWebhookUrl: 'https://discord.com/api/webhooks/x/y', fetch }

    await expect(handle(payload as unknown as AirtableWebhookPayload, config)).rejects.toThrow(
      'Missing required field: createdTime (string)'
    )
  })

  it('throws error with status and endpoint on non-2xx response', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ message: 'Invalid Webhook Token' }, 401))
    const payload: AirtableWebhookPayload = {
      id: 'rec123',
      fields: { Name: 'Test' },
      createdTime: '2024-01-01T00:00:00.000Z'
    }
    const config: ConnectorConfig = {
      discordWebhookUrl: 'https://discord.com/api/webhooks/invalid/token',
      fetch
    }

    await expect(handle(payload, config)).rejects.toThrow(
      'Discord webhook request failed: 401 Unauthorized at https://discord.com/api/webhooks/invalid/token'
    )
  })

  it('handles empty fields object gracefully', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://discord.com/api/webhooks/abc/def'
        ? jsonResponse({ id: 'msg123', channel_id: 'chan456', content: 'rec123' }, 200)
        : jsonResponse({ error: 'not found' }, 404)
    )

    const payload: AirtableWebhookPayload = {
      id: 'rec123',
      fields: {},
      createdTime: '2024-06-15T12:00:00.000Z'
    }

    const config: ConnectorConfig = {
      discordWebhookUrl: 'https://discord.com/api/webhooks/abc/def',
      fetch
    }

    const result = await handle(payload, config)

    expect(result.discordMessageId).toBe('msg123')
    expect(calls[0].json).toEqual({
      content: 'rec123',
      embeds: [{ fields: [], timestamp: '2024-06-15T12:00:00.000Z' }]
    })
